<template>
  <div class="kit-editor">
    <div class="kit-workspace">
      <div class="kit-stage"><RomImage :matrix="resource.matrix" :colors="previewColors" :label="$t('Uniforme modificado')" /><div class="rotation"><button :aria-label="$t('Anterior')" @click="rotate(-1)">‹</button><span>{{$t(directions[direction])}}</span><button :aria-label="$t('Siguiente')" @click="rotate(1)">›</button></div></div>
      <div class="garments" :aria-label="$t('Prenda')"><button v-for="part in garments" :key="part.label" :class="{selected:selectedLabel===part.label}" :aria-pressed="selectedLabel===part.label" @click="selectPart(part.label)"><span>{{$t(part.label)}}</span><span class="mini-swatches"><i v-for="entry in part.colors" :key="entry.index" :style="{background:entry.color}" /></span></button></div>
    </div>
    <div class="color-panel">
      <div class="panel-heading"><strong>{{$t(selectedPart.label)}}</strong><span class="tone-buttons"><button v-for="(entry,i) in selectedPart.colors" :key="entry.index" :class="{active:toneIndex===i}" :style="{background:entry.color}" :aria-label="i===0?$t('Color primario'):$t('Tono')+' '+(i+1)" :aria-pressed="toneIndex===i" @click="selectTone(i)"><span v-if="toneIndex===i">✓</span></button></span><button class="restore-color" :disabled="!selectedPart.colors.some(e=>modified(e.offset))" @click="restorePart">{{$t('Restaurar')}}</button></div>
      <div class="color-controls"><label class="main-color">{{$t(toneIndex===0?'Color primario':'Tono')}}<input type="color" :disabled="drawingPending" :aria-label="$t('Elegir color')" :value="draftColor" @input="inputColor($event.target.value)" @change="commitColor($event.target.value)" /></label><div class="rgb-controls"><label v-for="(channel,i) in ['R','G','B']" :key="channel"><b>{{channel}}</b><input type="range" :disabled="drawingPending" min="0" max="31" :value="rgb[i]" :aria-label="'RGB '+channel" @input="setChannel(i,$event.target.value)" @change="commitColor(draftColor)" /><input type="number" :disabled="drawingPending" min="0" max="31" :value="rgb[i]" :aria-label="'RGB '+channel+' 0–31'" @input="setChannel(i,$event.target.value)" @change="commitColor(draftColor)" /></label></div></div>
      <p v-if="drawingPending">{{$t('Aplica o descarta el dibujo pendiente antes de cambiar los colores.')}}</p><div v-if="pendingPrimary" class="tone-question" role="group" :aria-label="$t('Tonos automáticos')"><strong>{{$t('¿Generar los demás tonos de esta prenda automáticamente?')}}</strong><p>{{$t('Se crearán tonos claros del mismo color. Solo cambia esta prenda del equipo seleccionado.')}}</p><div class="suggested-tones"><i v-for="color in proposedTones" :key="color" :style="{background:color}" /></div><button class="primary-action" @click="resolveTones(true)">{{$t('Sí, generar tonos')}}</button><button @click="resolveTones(false)">{{$t('Solo el color primario')}}</button><button @click="cancelColor">{{$t('Cancelar')}}</button></div>
    </div>
    <details class="advanced"><summary>{{$t('Piel, pelo y otros colores')}}</summary><div class="extra-parts"><button v-for="part in extras" :key="part.label" :aria-pressed="selectedLabel===part.label" @click="selectPart(part.label)">{{$t(part.label)}} <span class="mini-swatches"><i v-for="entry in part.colors" :key="entry.index" :style="{background:entry.color}" /></span></button></div></details>
    <button class="drawing-toggle" :aria-expanded="drawingOpen" @click="toggleDrawing">{{$t(drawingOpen?'Cerrar dibujo por píxeles':'Dibujar camiseta y pantalón')}}</button>
    <div v-if="drawingOpen" class="drawing-panel"><p>{{$t('Dibuja sobre las prendas del sprite real. El patrón de píxeles se comparte entre equipos y entre los dos uniformes; cada equipo conserva sus colores. Cada dirección usa sus propios tiles, aunque algunos se reutilizan.')}}</p><label>{{$t('Zona de dibujo')}} <select :value="zone" @change="changeZone($event)"><option value="all">{{$t('Todas las prendas')}}</option><option value="shirt">{{$t('Camiseta')}}</option><option value="pants">{{$t('Pantalón')}}</option><option value="socks">{{$t('Medias')}}</option></select></label><PixelEditor @pending-change="drawingPending=$event" ref="pixel" :key="table+':'+direction+':'+zone" :matrix="resource.matrix" :colors="resource.colors" :original="original.matrix" :original-colors="original.colors" :editable="mask" :normalize-edit="normalizeDrawing" :highlight-editable="true" :apply-error="error" @apply="matrix=>$emit('draw',resource,matrix)" /></div>
  </div>
</template>
<script>
import PixelEditor from './PixelEditor.vue';
import RomImage from './RomImage.vue';
import {kitSections,kitDrawingResource,kitDrawingMask,normalizeKitDrawing,kitToneColors} from '../rom/kits.mjs';
export default {
 components:{PixelEditor,RomImage},props:{rom:Uint8Array,baseline:Uint8Array,team:Number,originalTeam:Number,table:Number,error:String,modified:Function},emits:['colors','restore-colors','draw'],
 data(){return {selectedLabel:'Camiseta',toneIndex:0,draft:null,pendingPrimary:false,drawingOpen:false,drawingPending:false,direction:0,zone:'all',directions:['Abajo','Diagonal abajo derecha','Derecha','Diagonal arriba derecha','Arriba','Diagonal arriba izquierda','Izquierda','Diagonal abajo izquierda']};},
 computed:{parts(){return kitSections(this.rom,this.team,this.table);},garments(){return this.parts.filter(p=>['Camiseta','Pantalón','Medias','Pantalón y medias'].includes(p.label));},extras(){return this.parts.filter(p=>!this.garments.includes(p));},selectedPart(){return this.parts.find(p=>p.label===this.selectedLabel)||this.garments[0];},entry(){return this.selectedPart.colors[this.toneIndex]||this.selectedPart.colors[0];},draftColor(){return this.draft||this.entry.color;},rgb(){return [1,3,5].map(i=>Math.round(parseInt(this.draftColor.slice(i,i+2),16)*31/255));},proposedTones(){return kitToneColors(this.draftColor,this.selectedPart.colors.length);},previewColors(){const colors=this.resource.colors.slice(),base=this.table===0x10326?1:0;if(this.draft){const values=this.pendingPrimary?this.proposedTones:[this.draftColor];if(this.pendingPrimary)this.selectedPart.colors.forEach((e,i)=>colors[e.index+base]=values[i]);else colors[this.entry.index+base]=this.draftColor;}return colors;},resource(){return kitDrawingResource(this.rom,this.team,this.table,this.direction);},original(){return kitDrawingResource(this.baseline,this.originalTeam,this.table,this.direction);},mask(){return kitDrawingMask(this.original,this.zone,this.table===0x10326);},dirty(){return !!this.draft||this.pendingPrimary||this.drawingOpen&&this.drawingPending;}},
 methods:{
  canLeave(){if(!this.dirty)return true;if(!confirm(this.$t('Hay una previsualización que todavía no se aplicó a la ROM. ¿Descartar esa previsualización?')))return false;this.cancelColor();if(this.drawingPending){this.drawingOpen=false;this.drawingPending=false;}return true;},
  cancelColor(){this.draft=null;this.pendingPrimary=false;},
  selectPart(label){if(label===this.selectedLabel)return;if(!this.canLeave())return;this.cancelColor();this.selectedLabel=label;this.toneIndex=0;},
  selectTone(index){if(index===this.toneIndex)return;if(!this.canLeave())return;this.cancelColor();this.toneIndex=index;},
  inputColor(color){if(this.drawingOpen&&this.drawingPending)return;this.draft=color;},
  setChannel(index,value){const v=Number(value);if(!Number.isInteger(v)||v<0||v>31)return;const channels=this.rgb.slice();channels[index]=v;this.inputColor('#'+channels.map(c=>Math.round(c*255/31).toString(16).padStart(2,'0')).join(''));},
  commitColor(color){if(this.drawingOpen&&this.drawingPending)return;this.draft=color;if(this.toneIndex===0&&this.selectedPart.colors.length>1&&this.garments.includes(this.selectedPart)){this.pendingPrimary=true;return;}const changes=[{index:this.entry.index,color}];this.cancelColor();this.$emit('colors',changes);},
  resolveTones(automatic){const entries=automatic?this.selectedPart.colors.map((entry,i)=>({index:entry.index,color:this.proposedTones[i]})):[{index:this.entry.index,color:this.draftColor}];this.cancelColor();this.$emit('colors',entries);},
  restorePart(){if(!this.canLeave())return;const offsets=this.selectedPart.colors.map(e=>e.offset);this.cancelColor();this.$emit('restore-colors',offsets);},
  rotate(delta){if(!this.canLeave())return;this.cancelColor();this.direction=(this.direction+delta+8)%8;},
  toggleDrawing(){const next=!this.drawingOpen;if(!this.canLeave())return;this.cancelColor();this.drawingPending=false;this.drawingOpen=next;},
  changeZone(event){if(!this.canLeave()){event.target.value=this.zone;return;}this.zone=event.target.value;},
  normalizeDrawing(matrix,before){return normalizeKitDrawing(this.resource,matrix,before);}
 }
};
</script>
<style scoped>
.kit-editor{max-width:820px;margin:20px 0}.kit-workspace{display:grid;grid-template-columns:minmax(200px,1fr) minmax(180px,1fr);gap:24px;align-items:center}.kit-stage{background:linear-gradient(#dce9f4 62%,#89ad83 62%);border:1px solid #bacbd8;border-radius:12px;padding:20px 18px 8px;text-align:center}.kit-stage :deep(canvas){height:220px;max-width:100%;border:0;background:transparent}.rotation{display:flex;justify-content:space-between;align-items:center;margin-top:12px;font-size:13px}.rotation button{font-size:24px;line-height:1;padding:3px 12px}.garments{display:grid;gap:12px}.garments>button{display:flex;align-items:center;justify-content:space-between;gap:12px;text-align:left;background:white;border:1px solid #c3cfdd;border-radius:10px;padding:18px;font-size:16px;color:#24374b}.garments>button.selected{border:2px solid #2465d7;background:#eef5ff;font-weight:700}.mini-swatches{display:inline-flex;gap:2px}.mini-swatches i{width:17px;height:22px;border:1px solid #0002;border-radius:2px}.color-panel{margin-top:20px;border:1px solid #c3cfdd;border-radius:12px;background:#fff;padding:18px}.panel-heading{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.tone-buttons{display:flex;gap:6px}.tone-buttons button{width:38px;height:34px;border:2px solid #fff;border-radius:5px;box-shadow:0 0 0 1px #bbc6d2}.tone-buttons button.active{box-shadow:0 0 0 2px #2465d7}.tone-buttons span{color:white;text-shadow:0 1px 3px #000;font-weight:bold}.restore-color{margin-left:auto}.color-controls{display:flex;gap:24px;margin-top:18px;align-items:center}.main-color{display:grid;gap:8px;font-size:13px}.main-color input{width:76px;height:64px;border:1px solid #bbc6d2;border-radius:8px;padding:3px;background:white}.rgb-controls{display:grid;gap:10px;flex:1}.rgb-controls label{display:flex;gap:10px;align-items:center}.rgb-controls input[type=range]{min-width:60px;flex:1}.rgb-controls input[type=number]{width:52px}.tone-question{margin-top:18px;background:#eef5ff;border:1px solid #bfd4f8;border-radius:8px;padding:16px}.tone-question p{margin:8px 0;font-size:14px}.suggested-tones{display:flex;margin:12px 0}.suggested-tones i{height:24px;width:46px}.tone-question button{margin:4px 8px 4px 0}.primary-action{background:#2465d7;color:white;border:1px solid #2465d7}.advanced{margin:16px 0;border-bottom:1px solid #d4dde6;padding-bottom:16px}.advanced summary{cursor:pointer}.extra-parts{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.extra-parts button{display:flex;gap:12px;align-items:center}.drawing-toggle{margin-top:4px}.drawing-panel{margin-top:16px}.drawing-panel>p{font-size:14px;line-height:1.5}@media(max-width:540px){.kit-workspace{grid-template-columns:1fr;gap:12px}.kit-stage :deep(canvas){height:180px}.garments{display:flex;gap:6px}.garments>button{flex:1;flex-direction:column;padding:12px 6px;font-size:14px}.color-controls{gap:12px}.color-panel{padding:12px}.restore-color{font-size:12px}}
</style>
